#include <stdio.h>

double f(double x) { return 2*x*x*x - 4*x*x + 3*x + 6; }

int main(void) {
    double left = -10, right = 10;
    while (right - left >= 1e-8) {
        double middle = (left + right) / 2;
        if (f(left) * f(middle) <= 0) right = middle;
        else left = middle;
    }
    printf("%.6f\n", (left + right) / 2);
    return 0;
}
